def solve(grid):
    """Return number of islands (4-directionally connected 1s) in a possibly ragged grid.
    Handles empty grid and rows of varying lengths.
    """
    # collect coordinates of land cells
    land = {(i, j) for i, row in enumerate(grid) for j, val in enumerate(row) if val == 1}
    islands = 0
    while land:
        islands += 1
        stack = [land.pop()]  # start new island
        while stack:
            i, j = stack.pop()
            # check four neighbours
            for ni, nj in ((i-1, j), (i+1, j), (i, j-1), (i, j+1)):
                if (ni, nj) in land:
                    land.remove((ni, nj))
                    stack.append((ni, nj))
    return islands

