def solve(a, x):
    """Return leftmost insertion index for x in sorted list a.
    Uses binary search to find the first position where a[pos] >= x.
    If all elements are less than x, returns len(a).
    """
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

