def solve(n, edges):
    from heapq import heappush, heappop
    # Build adjacency list and indegree count
    adj = [[] for _ in range(n)]
    indeg = [0]*n
    for a,b in edges:
        if 0 <= a < n and 0 <= b < n:
            adj[a].append(b)
            indeg[b] += 1
    # Min-heap of nodes with indegree 0
    heap = []
    for i in range(n):
        if indeg[i]==0:
            heappush(heap,i)
